#ifndef ZOVUTILS_ID_BACKEND_H
#define ZOVUTILS_ID_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <unistd.h>
#include <pwd.h>
#include <grp.h>
static inline const char*zov_uid_name(uid_t id,char*b,size_t n){struct passwd*p=getpwuid(id);if(p)return p->pw_name;snprintf(b,n,"%lu",(unsigned long)id);return b;}
static inline const char*zov_gid_name(gid_t id,char*b,size_t n){struct group*p=getgrgid(id);if(p)return p->gr_name;snprintf(b,n,"%lu",(unsigned long)id);return b;}
static inline int zov_id_run(int argc,char**argv){int mode=0,names=0,real=0,context=0,all=0;for(int i=0;i<argc;i++){const char*a=argv[i];if(!strcmp(a,"--help")){puts("Usage: id [OPTION]... [USER]\nPrint user and group information for the specified USER, or the current user.\n  -a             ignore, for compatibility with other versions\n  -u, --user      print only the effective user ID\n  -g, --group     print only the effective group ID\n  -G, --groups    print all group IDs\n  -n, --name      print a name instead of a number\n  -r, --real      print the real ID instead of the effective ID\n  -Z, --context   print only the security context\n      --help      display this help and exit\n      --version   output version information and exit");return 0;}if(!strcmp(a,"--version")){puts("id (zovutils) 0.10.49");return 0;}if(!strcmp(a,"-a")){all=1;continue;}if(!strcmp(a,"-n")||!strcmp(a,"--name")){names=1;continue;}if(!strcmp(a,"-r")||!strcmp(a,"--real")){real=1;continue;}if(!strcmp(a,"-Z")||!strcmp(a,"--context")){context=1;continue;}if(!strcmp(a,"-u")||!strcmp(a,"--user")){if(mode){fprintf(stderr,"id: cannot print only user and only group\n");return 1;}mode=1;continue;}if(!strcmp(a,"-g")||!strcmp(a,"--group")){if(mode){fprintf(stderr,"id: cannot print only user and only group\n");return 1;}mode=2;continue;}if(!strcmp(a,"-G")||!strcmp(a,"--groups")){mode=3;continue;}if(a[0]=='-'&&a[1]&&a[1]!='-'){int valid=1;for(size_t j=1;a[j];j++){if(a[j]=='u'){if(mode&&mode!=1)valid=0;mode=1;}else if(a[j]=='g'){if(mode&&mode!=2)valid=0;mode=2;}else if(a[j]=='G')mode=3;else if(a[j]=='n')names=1;else if(a[j]=='r')real=1;else if(a[j]=='a')all=1;else if(a[j]=='Z')context=1;else valid=0;}if(valid)continue;}if(a[0]=='-'&&strcmp(a,"-")){fprintf(stderr,"id: unrecognized option '%s'\nTry 'id --help' for more information.\n",a);return 1;}fprintf(stderr,"id: cannot print information for a user other than the current one\n");return 1;}uid_t uid=real?getuid():geteuid();gid_t gid=real?getgid():getegid();if(real&&!mode){fprintf(stderr,"id: '-r' is only permitted with -u or -g\nTry 'id --help' for more information.\n");return 1;}if(names&&mode!=1&&mode!=2&&mode!=3){fprintf(stderr,"id: '-n' is only permitted with -u, -g, or -G\nTry 'id --help' for more information.\n");return 1;}if(mode==1){if(names)puts(zov_uid_name(uid,(char[32]){0},32));else printf("%lu\n",(unsigned long)uid);return 0;}if(mode==2){if(names)puts(zov_gid_name(gid,(char[32]){0},32));else printf("%lu\n",(unsigned long)gid);return 0;}if(mode==3){int n=getgroups(0,NULL);if(n<0){fprintf(stderr,"id: cannot get groups: %s\n",strerror(errno));return 1;}gid_t*gs=(gid_t*)malloc((size_t)(n+1)*sizeof(gid_t));if(!gs)return 1;if(getgroups(n,gs)<0){free(gs);return 1;}int first=1;if(names)fputs(zov_gid_name(gid,(char[32]){0},32),stdout);else printf("%lu",(unsigned long)gid);first=0;for(int i=0;i<n;i++)if(gs[i]!=gid){putchar(' ');if(names)fputs(zov_gid_name(gs[i],(char[32]){0},32),stdout);else printf("%lu",(unsigned long)gs[i]);}putchar('\n');free(gs);(void)first;return 0;}if(context){FILE*f=fopen("/proc/self/attr/current","r");if(!f){fprintf(stderr,"id: cannot get security context: %s\n",strerror(errno));return 1;}char b[4096];if(!fgets(b,sizeof(b),f)){fclose(f);return 1;}fclose(f);b[strcspn(b,"\r\n")]=0;puts(b);return 0;}char un[32],gn[32];printf("uid=%lu(%s) gid=%lu(%s)",(unsigned long)uid,zov_uid_name(uid,un,sizeof(un)),(unsigned long)gid,zov_gid_name(gid,gn,sizeof(gn)));int n=getgroups(0,NULL);gid_t*gs=(gid_t*)malloc((size_t)(n+1)*sizeof(gid_t));if(!gs)return 1;if(n>0&&getgroups(n,gs)<0){free(gs);return 1;}fputs(" groups=",stdout);if(n==0||gs[0]!=gid){printf("%lu(%s)",(unsigned long)gid,zov_gid_name(gid,gn,sizeof(gn)));}for(int i=0;i<n;i++)if(gs[i]!=gid){putchar(',');printf("%lu(%s)",(unsigned long)gs[i],zov_gid_name(gs[i],gn,sizeof(gn)));}free(gs);if(access("/sys/fs/selinux",F_OK)==0){FILE*f=fopen("/proc/self/attr/current","r");if(f){char b[4096];size_t k=0;int ch;while(k+1<sizeof(b)&&(ch=fgetc(f))!=EOF&&ch!='\n')b[k++]=(char)ch;b[k]=0;if(*b)printf(" context=%s",b);fclose(f);}}putchar('\n');(void)all;return 0;}
#endif
